using System.Net;
using System.Net.Http.Json;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using GaoApp.Web.Services.CustomerService;
using Xunit;
namespace GaoApp.Tests.Security;
public sealed partial class CustomerChannelTransportTests:IDisposable
{
    private readonly string directory=Path.Combine(Path.GetTempPath(),"GaoChannelWireTests",Guid.NewGuid().ToString("N"));
    internal readonly AssistantIntegrationTests.FixedClock Clock=new();
    public CustomerChannelTransportTests(){Directory.CreateDirectory(Path.Combine(directory,"credentials"));File.WriteAllText(Path.Combine(directory,"credentials","token"),"SYNTHETIC_BEARER_TOKEN_ONLY");}
    internal static CustomerChannelConnection Facebook()=>new(){Id="facebook-test",Provider="facebook",StoreId=1,AccountId="123456",Enabled=true,GraphVersion="v26.0",AccessTokenFile="token",AppSecretFile="secret",VerifyTokenFile="verify"};
    private CustomerChannelRegistry Registry(CustomerChannelConnection c){
        c.AccessTokenFile=Path.GetFullPath(c.AccessTokenFile,Path.Combine(directory,"credentials"));if(c.AppSecretFile!="")c.AppSecretFile=Path.GetFullPath(c.AppSecretFile,Path.Combine(directory,"credentials"));if(c.VerifyTokenFile!="")c.VerifyTokenFile=Path.GetFullPath(c.VerifyTokenFile,Path.Combine(directory,"credentials"));
        return new(new AssistantIntegrationTests.Monitor<CustomerChannelOptions>(new(){CredentialDirectory=Path.Combine(directory,"credentials"),Connections=[c]}),new AssistantIntegrationTests.EnvironmentStub(Path.Combine(directory,"web")));
    }
    private CustomerChannelDispatch Item(string? job=null)=>new(Guid.NewGuid(),Guid.NewGuid(),"test","binding","999111","42","TEST text","agent",1,job is null?"pending":"accepted",job,Clock.Now,0);
    internal sealed class Handler(Func<HttpRequestMessage,Task<HttpResponseMessage>> handle):HttpMessageHandler {protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct)=>handle(request);}
    internal static HttpResponseMessage Json(object value)=>new(HttpStatusCode.OK){Content=JsonContent.Create(value)};
    [Fact]public void Facebook_signs_raw_UTF8_bytes_and_rejects_wrong_or_reformatted_payload(){var raw=Encoding.UTF8.GetBytes("{\"text\":\"sữa tươi\"}");var secret="SYNTHETIC_APP_SECRET";var signature="sha256="+Convert.ToHexString(HMACSHA256.HashData(Encoding.UTF8.GetBytes(secret),raw)).ToLowerInvariant();Assert.True(CustomerChannelTransport.VerifyFacebook(secret,raw,signature));Assert.False(CustomerChannelTransport.VerifyFacebook(secret,Encoding.UTF8.GetBytes("{ \"text\":\"sữa tươi\"}"),signature));Assert.False(CustomerChannelTransport.VerifyFacebook(secret+"x",raw,signature));Assert.False(CustomerChannelTransport.VerifyFacebook(secret,raw,"sha256="+new string('z',64)));}
    private JsonElement Event(object payload,string page="123456")=>JsonSerializer.SerializeToElement(new{@object="page",entry=new[]{new{id=page,messaging=new[]{new{sender=new{id="999111"},recipient=new{id=page},timestamp=Clock.Now.ToUnixTimeMilliseconds(),message=payload}}}}});
    [Fact]public void Facebook_extracts_text_and_ignores_echo_without_looping(){var c=Facebook();Assert.Single(CustomerChannelTransport.FacebookMessages(c,Event(new{mid="one",text="TEST text"}),Clock.Now));Assert.Empty(CustomerChannelTransport.FacebookMessages(c,Event(new{mid="echo",text="TEST",is_echo=true}),Clock.Now));}
    [Fact]public void Facebook_media_goes_to_human_without_fetching_attachment_urls(){var item=Assert.Single(CustomerChannelTransport.FacebookMessages(Facebook(),Event(new{mid="media",attachments=new[]{new{type="image",payload=new{url="http://127.0.0.1/private"}}}}),Clock.Now));Assert.True(item.NeedsHuman);Assert.DoesNotContain("127.0.0.1",item.Text);}
    [Fact]public void Facebook_wrong_page_or_duplicate_JSON_is_rejected(){Assert.ThrowsAny<Exception>(()=>CustomerChannelTransport.FacebookMessages(Facebook(),Event(new{mid="one",text="TEST"},"other-page"),Clock.Now));using var duplicate=JsonDocument.Parse("{\"object\":\"page\",\"object\":\"page\",\"entry\":[]}");Assert.ThrowsAny<Exception>(()=>CustomerChannelTransport.FacebookMessages(Facebook(),duplicate.RootElement,Clock.Now));}
    [Fact]public async Task Facebook_send_uses_bearer_and_fixed_graph_endpoint_without_token_in_URL(){var c=Facebook();using var http=new HttpClient(new Handler(async r=>{Assert.Equal("https://graph.facebook.com/v26.0/123456/messages",r.RequestUri!.ToString());Assert.Equal("Bearer SYNTHETIC_BEARER_TOKEN_ONLY",r.Headers.Authorization!.ToString());var body=JsonDocument.Parse(await r.Content!.ReadAsStringAsync()).RootElement;Assert.Equal("999111",body.GetProperty("recipient").GetProperty("id").GetString());Assert.Equal("RESPONSE",body.GetProperty("messaging_type").GetString());return Json(new{recipient_id="999111",message_id="test-mid"});}));var result=await new CustomerChannelTransport(http,Registry(c),Clock).Dispatch(c,Item(),default);Assert.Equal("sent",result.State);Assert.Equal("test-mid",result.ExternalId);}
    [Theory][InlineData(500,"review")][InlineData(429,"failed")][InlineData(403,"failed")]
    public async Task Facebook_does_not_automatically_retry_an_uncertain_send(int status,string expected){var calls=0;var c=Facebook();using var http=new HttpClient(new Handler(r=>{calls++;return Task.FromResult(new HttpResponseMessage((HttpStatusCode)status));}));Assert.Equal(expected,(await new CustomerChannelTransport(http,Registry(c),Clock).Dispatch(c,Item(),default)).State);Assert.Equal(1,calls);}
    [Fact]public async Task Facebook_rejects_a_success_response_for_a_different_recipient(){var c=Facebook();using var http=new HttpClient(new Handler(r=>Task.FromResult(Json(new{recipient_id="WRONG",message_id="mid"}))));Assert.Equal("review",(await new CustomerChannelTransport(http,Registry(c),Clock).Dispatch(c,Item(),default)).State);}
    private CustomerChannelConnection Zalo()=>new(){Id="zalo-test",Provider="zalomarketing",StoreId=1,AccountId=Guid.NewGuid().ToString(),BaseUrl="https://zalo.example.test/",AccessTokenFile="token",Enabled=true};
    [Fact]public async Task Zalo_acceptance_is_not_sent_and_retry_preserves_idempotency_reference_and_content(){var c=Zalo();var peer=Guid.NewGuid();var item=Item() with{Peer=peer.ToString()};var requests=new List<(string Key,string Body)>();using var http=new HttpClient(new Handler(async r=>{requests.Add((r.Headers.GetValues("Idempotency-Key").Single(),await r.Content!.ReadAsStringAsync()));if(requests.Count==1)throw new HttpRequestException("TEST lost acknowledgement");var result=Json(new{jobId=Guid.NewGuid(),conversationId=peer,replyToSequence=42,status="Pending",idempotencyReplayed=true});result.Headers.Add("X-ZaloMarketing-Sender-Profile-Id",c.AccountId);return result;}));var wire=new CustomerChannelTransport(http,Registry(c),Clock);Assert.Equal("retry",(await wire.Dispatch(c,item,default)).State);Assert.Equal("accepted",(await wire.Dispatch(c,item with{Attempts=1},default)).State);Assert.Equal(requests[0],requests[1]);}
    [Fact]public async Task Zalo_job_poll_is_read_only_and_checks_sender_profile(){var c=Zalo();var job=Guid.NewGuid();var calls=0;using var http=new HttpClient(new Handler(r=>{calls++;Assert.Equal(HttpMethod.Get,r.Method);Assert.EndsWith("api/v1/jobs/"+job,r.RequestUri!.ToString());return Task.FromResult(Json(new{jobId=job,senderProfileId=Guid.Parse(c.AccountId),status="Completed",summary=new{total=1,sent=1,needsReview=0,partiallySent=0,failed=0,notFound=0,skipped=0}}));}));Assert.Equal("sent",(await new CustomerChannelTransport(http,Registry(c),Clock).Dispatch(c,Item(job.ToString()),default)).State);Assert.Equal(1,calls);}
    [Fact]public async Task Zalo_wrong_sender_profile_is_reviewed_without_sending_again(){var c=Zalo();var job=Guid.NewGuid();using var http=new HttpClient(new Handler(r=>Task.FromResult(Json(new{jobId=job,senderProfileId=Guid.NewGuid(),summary=new{total=1,sent=1}}))));Assert.Equal("review",(await new CustomerChannelTransport(http,Registry(c),Clock).Dispatch(c,Item(job.ToString()),default)).State);}
    [Fact]public async Task Zalo_never_resubmits_after_the_idempotency_window(){var c=Zalo();var calls=0;using var http=new HttpClient(new Handler(r=>{calls++;return Task.FromResult(Json(new{}));}));Assert.Equal("review",(await new CustomerChannelTransport(http,Registry(c),Clock).Dispatch(c,Item() with{CreatedAt=Clock.Now.AddHours(-24)},default)).State);Assert.Equal(0,calls);}
    [Fact]public void Configuration_rejects_duplicate_account_mapping_and_disabled_options_need_no_secrets(){var a=Facebook();var b=Facebook();b.Id="another-store";b.StoreId=2;Assert.False(new CustomerChannelOptions{Connections=[a,b]}.Valid());Assert.True(new CustomerChannelOptions().Valid());a.Enabled=false;a.AccessTokenFile="";Assert.True(new CustomerChannelOptions{Connections=[a]}.Valid());}
    [Fact]public void Sender_profile_case_cannot_map_one_Zalo_account_to_two_stores(){var id=Guid.NewGuid().ToString("D");var a=new CustomerChannelConnection{Id="zalo-one",Provider="zalomarketing",StoreId=1,AccountId=id.ToUpperInvariant()};var b=new CustomerChannelConnection{Id="zalo-two",Provider="zalomarketing",StoreId=2,AccountId=id.ToLowerInvariant()};Assert.False(new CustomerChannelOptions{Connections=[a,b]}.Valid());}
    public void Dispose(){if(Directory.Exists(directory))Directory.Delete(directory,true);}
}